def clean(df):
    df = df.copy()
    df['Category'] = df['Category'].replace({
        'accessories': 'Accessories',
        'office supplies': 'Office Supplies',
        'Furnture': 'Furniture'
    })
    df = df.drop_duplicates()
    return df

def answer(df):
    counts = df.groupby('Category').size().to_dict()
    return counts
